  IF EXISTS(SELECT 1 FROM public.figure_sources actual WHERE actual.figure_id IN (SELECT (row_data->>'id')::uuid FROM lh_expected WHERE table_name='historical_figures') AND NOT EXISTS(SELECT 1 FROM lh_expected e WHERE e.table_name='figure_sources' AND to_jsonb(actual)->'figure_id'=e.row_data->'figure_id' AND to_jsonb(actual)->'claim_key'=e.row_data->'claim_key' AND to_jsonb(actual)->'source_id'=e.row_data->'source_id')) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='UNEXPECTED_GRAPH_LINK:figure_sources'; END IF;
