SELECT pg_temp.lh_import_drafts();
-- Explicitly disposable, uncommitted promotion; never a national release.
SET LOCAL ROLE authenticated;
DO $lh_promote$ DECLARE outcome jsonb; BEGIN
  PERFORM set_config('request.jwt.claim.sub','a7070000-0000-4000-8000-000000000001',true);
    outcome:=public.local_hero_submit_graph(jsonb_build_object('figureId','c0bcb4b3-9a6a-4f02-aae5-2d38dbc3c15a','expectedRevision',(SELECT local_hero_revision::text FROM public.historical_figures WHERE id='c0bcb4b3-9a6a-4f02-aae5-2d38dbc3c15a'::uuid),'storyIds',jsonb_build_array('a3cbabb1-6fdc-53f8-9e03-f250108252f5')));
